(function(){
  let pid=1, mid=1;
  TRAW.forEach(sec=>{
    for(let i=0;i<sec.masael.length;i+=3){
      const chunk = sec.masael.slice(i,i+3).map(m=>({id: mid++, ...m}));
      const page = { id: pid++, kitab: sec.kitab, bab: sec.bab, masael: chunk };
      window.TAWHID.pages.push(page);
      chunk.forEach(m=> window.TAWHID.flat.push({...m, pageId: page.id, kitab: sec.kitab, bab: sec.bab}));
    }
  });
})();
